    /** @param array<string, array{string, bool}> $expected property name => [field name, has normalizer] */
    private function metadata(string $class, array $expected): ClassMetadata
    {
        $metadata = $this->hydrator()->metadata($class);
        $actual = [];

        foreach ($metadata->properties as $property) {
            $actual[$property->propertyName] = [$property->fieldName, $property->normalizer !== null];
        }

