    private function inlineObject(Normalizer $normalizer, string $class, Skip $direction): bool
    {
        if (!$normalizer instanceof ObjectNormalizer) {
            return false;
        }

        try {
            if ($normalizer->className() !== $class) {
                return false;
            }
        } catch (Throwable) {
            return false;
        }

        return $this->inlinable($class, $direction);
    }

    private function inlineArray(Normalizer $normalizer, string $class, Skip $direction): bool
    {
        return $normalizer instanceof ArrayNormalizer && $this->inlineObject($normalizer->innerNormalizer(), $class, $direction);
    }

    /**
     * Nested objects are only inlined when this does not change the behaviour: the nested class must be handled
     * by this middleware, must not be lazy and every other middleware must skip the class in this direction.
     */
    private function inlinable(string $class, Skip $direction): bool
    {
        try {
            $metadata = $this->hydrator()->metadata($class);
        } catch (Throwable) {
            return false;
        }

        if ($metadata->normalizer !== null) {
            return false;
        }

        if (\PHP_VERSION_ID >= 80400 && ($metadata->lazy ?? $this->hydrator()->defaultLazy())) {
            return false;
        }

        return $this->exclusive($metadata, $direction);
    }

    /** Whether every other middleware skips the class in this direction, so this middleware is the only one to run. */
    private function exclusive(ClassMetadata $metadata, Skip $direction): bool
    {
        foreach ($this->others as $middleware) {
            if (!$middleware instanceof SkippableMiddleware) {
                return false;
            }

            $skip = $middleware->skip($metadata);

            if ($skip !== Skip::Both && $skip !== $direction) {
                return false;
            }
        }

        return true;
    }
}

